    def __init__(self, rate, burst):
        if rate <= 0:
            raise ValueError("rate must be positive")
        if burst < 1:
            raise ValueError("burst must be at least 1")

        self.rate = rate
        self.burst = burst
        # key -> (last_time, tokens_left)
        self._keys = {}

    def allow(self, key, now):
        if key not in self._keys:
            # New key starts full
            self._keys[key] = (now, self.burst)

        last_time, left = self._keys[key]

        # Check if time went backwards for this key
        if now < last_time:
            raise ValueError("time went backwards")

        # Refill tokens based on elapsed time
        elapsed = now - last_time
        new_left = min(self.burst, left + self.rate * elapsed)

        # Update the stored state
        self._keys[key] = (now, new_left)

        # Consume one token if available
        if new_left >= 1:
            self._keys[key] = (now, new_left - 1)
            return True
        else:
            return False
